CREATE TABLE P_LEW_MART_MSI.T_AGG_NET_VGES_MTH CLUSTER BY (CY_MONTH) COMMENT = 'Table contains the base data for the Report Nettoleistung 1104004.312. Data is provided by store and calendar month.'
